export const DECISION_MAKING_ACTIVITIES = [
{n:1,type:"mcq",micro:"Apa itu keputusan",q:"'Mengambil keputusan' berarti...",options:["Memilih satu tindakan dari beberapa pilihan yang mungkin","Menghindari semua pilihan yang ada supaya tidak perlu menanggung akibat dari tindakan apa pun","Membiarkan orang lain memilih untukmu, lalu menerima begitu saja apa pun yang mereka putuskan"],answer:0,explain:"Keputusan adalah memilih di antara beberapa jalan yang terbuka, lalu berkomitmen pada pilihan itu.",hint:"Apa yang kamu lakukan saat ada beberapa jalan dan hanya bisa lewat satu?"},
{n:2,type:"mcq",micro:"Keputusan vs masalah",q:"'Haruskah aku ikut klub musik atau klub sains?' lebih tepat disebut...",options:["Masalah karena ada hambatan","Keputusan — memilih di antara beberapa opsi yang sama-sama mungkin","Bukan keduanya"],answer:1,explain:"Masalah punya hambatan yang menghalangi tujuan; keputusan adalah memilih di antara jalan yang terbuka.",hint:"Ada yang menghalangimu, atau kamu hanya perlu memilih?"},
{n:3,type:"mcq",micro:"Pilihan (opsi)",q:"Sebelum memutuskan, langkah yang membantu adalah...",options:["Langsung mengambil pilihan yang pertama terpikir tanpa membandingkannya dengan pilihan lain yang ada","Menunggu saja tanpa berpikir apa pun sampai keadaan memaksa kita memilih salah satu dengan sendirinya","Mendaftar pilihan-pilihan yang tersedia, termasuk 'tidak melakukan apa-apa'"],answer:2,explain:"Keputusan yang baik dimulai dari mengetahui pilihan apa saja yang sebenarnya ada.",hint:"Bagaimana kamu memilih tanpa tahu apa saja pilihannya?"},
{n:4,type:"mcq",micro:"Kriteria",q:"'Kriteria' untuk sebuah keputusan adalah...",options:["Hal-hal yang penting bagimu, yang kamu pakai untuk membandingkan pilihan (biaya, waktu, kesenangan, manfaat jangka panjang)","Nama-nama pilihan yang tersedia, yang dituliskan berurutan dari yang pertama sampai terakhir, tanpa ada hubungannya dengan apa yang penting bagimu","Hanya pendapat orang lain tentang pilihan itu, yang kamu pakai sebagai pengganti penilaianmu sendiri tentang biaya, waktu, dan manfaatnya bagimu"],answer:0,explain:"Kriteria membuat perbandingan jelas: pilihan mana yang paling memenuhi hal-hal yang kamu anggap penting.",hint:"Apa yang kamu pedulikan dalam keputusan ini?"},
{n:5,type:"mcq",micro:"Akibat",q:"Setiap pilihan punya 'akibat' — yaitu...",options:["Perasaanmu sekarang","Apa yang kemungkinan terjadi kalau kamu memilih pilihan itu","Nama lain untuk pilihan"],answer:1,explain:"Membayangkan akibat tiap pilihan ('kalau aku pilih ini, lalu apa?') membantu memilih dengan mata terbuka.",hint:"Kalau kamu memilih A, apa yang mungkin terjadi setelahnya?"},
{n:6,type:"order",micro:"Langkah mengambil keputusan",q:"Urutkan langkah dasar mengambil keputusan.",items:["Perjelas keputusan apa yang harus diambil dan mengapa","Daftar pilihan yang tersedia","Pikirkan akibat & seberapa cocok tiap pilihan dengan kriteriamu","Pilih, lakukan, lalu tinjau hasilnya"],answer:[0,1,2,3],explain:"Perjelas → daftar pilihan → timbang akibat vs kriteria → pilih & tinjau.",hint:"Kamu perlu tahu keputusan apa yang dihadapi sebelum mendaftar pilihan."},
{n:7,type:"mcq",micro:"Pilihan 'tidak memutuskan'",q:"Menunda keputusan tanpa batas atau membiarkan keadaan yang memilih...",options:["Bukan sebuah pilihan sama sekali, sehingga tidak membawa akibat apa pun bagi kamu maupun orang lain","Selalu merupakan pilihan terbaik, karena dengan menunggu semua masalah pasti akan selesai dengan sendirinya","Sebenarnya juga sebuah pilihan, dengan akibatnya sendiri"],answer:2,explain:"'Tidak memilih' berarti memilih apa pun yang terjadi kalau tidak ada tindakan. Itu bukan cara menghindari konsekuensi.",hint:"Apa yang terjadi pada tiket konser kalau kamu 'menunda' membeli sampai habis?"},
{n:8,type:"mcq",micro:"Fakta vs perasaan",q:"Dalam keputusan, fakta ('les ini Rp200.000/bulan, jam 4 sore') dan perasaan ('aku gugup mencoba hal baru') keduanya...",options:["Berguna — fakta memberi gambaran nyata, perasaan memberi info tentang apa yang penting bagimu; pisahkan agar keduanya jelas","Hanya fakta yang boleh dipakai dalam memutuskan, sedangkan perasaan sebaiknya diabaikan sepenuhnya begitu saja","Hanya perasaan yang penting dalam memutuskan, sedangkan fakta seperti harga dan jam tidak perlu diperhatikan"],answer:0,explain:"Keputusan yang baik memakai keduanya secara sadar, tanpa mencampur-adukkannya.",hint:"Apa yang bisa diperiksa, dan apa yang menunjukkan nilai-nilaimu?"},
{n:9,type:"mcq",micro:"Keputusan kecil vs besar",q:"'Pensil mana yang kupakai' vs 'sekolah lanjutan mana yang kupilih' berbeda dalam...",options:["Keputusan kecil lebih penting","Besarnya akibat dan seberapa sulit dibatalkan — keputusan besar layak dipikirkan lebih lama","Tidak ada bedanya"],answer:1,explain:"Sesuaikan usaha berpikir dengan pentingnya keputusan. Keputusan sepele yang mudah dibatalkan tidak butuh analisis panjang.",hint:"Mana yang lebih sulit diubah setelah dipilih?"},
{n:10,type:"mcq",micro:"Reversibel vs permanen",q:"Keputusan yang 'mudah dibatalkan' (mencoba tempat duduk baru) bisa diambil...",options:["Sama hati-hatinya dengan keputusan permanen","Tidak boleh diambil","Lebih cepat dan dengan lebih sedikit analisis — kalau salah, tinggal kembali"],answer:2,explain:"Untuk keputusan yang bisa dibatalkan dengan mudah, 'coba dulu' sering lebih baik daripada berpikir lama.",hint:"Kalau kamu bisa mengubahnya besok tanpa rugi, seberapa lama kamu perlu menimbang?"},
{n:11,type:"tf",micro:"Keputusan butuh informasi cukup",q:"Benar atau Salah: Untuk keputusan penting, mengumpulkan informasi kunci lebih dulu (harga, jadwal, pengalaman orang lain) hanya membuang waktu dan tidak memperbaiki pilihan.",answer:false,explain:"Keputusan sebaik informasi yang mendasarinya, jadi mengumpulkan fakta kunci biasanya menghasilkan pilihan yang lebih baik. Yang perlu dihindari hanya membiarkan 'mengumpulkan info' jadi cara menunda selamanya.",hint:"Apakah lebih mudah memilih sekolah setelah mengunjunginya atau hanya menebak?"},
{n:12,type:"mcq",micro:"Biaya peluang dalam keputusan",q:"Memilih ikut klub A berarti tidak bisa ikut klub B yang jadwalnya bentrok. 'Kehilangan B' ini disebut...",options:["Biaya peluang — nilai pilihan terbaik yang kamu lepaskan","Kembalian","Bonus"],answer:0,explain:"Setiap keputusan punya biaya peluang. Menyadarinya membuat pilihan lebih jujur.",hint:"Apa yang kamu korbankan dengan memilih A?"},
{n:13,type:"mcq",micro:"Menuliskan pilihan dan kriteria",q:"Menuliskan pilihan dan kriteria (bukan hanya memikirkannya) berguna karena...",options:["Hanya untuk keputusan sepele","Membuat perbandingan terlihat jelas dan mengurangi lupa faktor penting","Membuang waktu"],answer:1,explain:"Untuk keputusan yang agak rumit, menuangkannya ke tulisan atau tabel membantu berpikir jernih.",hint:"Bisakah kamu membandingkan 4 pilihan pada 4 kriteria hanya di kepala tanpa lupa?"},
{n:14,type:"mcq",micro:"Menanyakan orang berpengalaman",q:"Sebelum memutuskan hal yang belum pernah kamu alami, berbicara dengan orang yang sudah pernah menjalaninya berguna karena...",options:["Mereka akan memutuskan untukmu, sehingga kamu tidak perlu menimbang pilihan yang ada dengan caramu sendiri","Pendapat mereka pasti benar untuk kamu juga, karena keadaan setiap orang selalu sama persis dalam hal ini","Mereka bisa menceritakan akibat nyata yang tidak terlihat dari luar"],answer:2,explain:"Pengalaman orang lain adalah informasi berharga — tapi keputusan akhir tetap milikmu karena keadaan tiap orang berbeda.",hint:"Apa yang orang yang sudah menjalani tahu yang tidak kamu ketahui?"},
{n:15,type:"mcq",micro:"Keputusan di bawah tekanan waktu",q:"Kalau harus memutuskan cepat, cara yang masuk akal:",options:["Kenali 2–3 pilihan utama, cek 1–2 kriteria terpenting, pilih yang paling masuk akal — jangan tunggu kepastian penuh","Tunggu sampai yakin 100%","Pilih acak"],answer:0,explain:"Keputusan cepat tetap bisa terstruktur, hanya dengan versi ringkas: pilihan utama, kriteria utama, pilih.",hint:"Bisakah kamu tetap menimbang meski waktunya sedikit?"},
{n:16,type:"tf",micro:"Keputusan bisa dievaluasi",q:"Benar atau Salah: Sekali keputusan diambil, meninjau kembali 'apakah ini tepat dan apa yang bisa kupelajari' tidak ada gunanya karena hasilnya sudah terjadi.",answer:false,explain:"Merefleksikan keputusan — terutama prosesnya, bukan hanya hasilnya — membangun penilaian yang lebih baik untuk keputusan berikutnya.",hint:"Bagaimana kamu menjadi lebih baik dalam memutuskan?"},
{n:17,type:"mcq",micro:"Keputusan yang melibatkan orang lain",q:"Kalau keputusan memengaruhi orang lain (memilih tempat wisata kelas), cara yang adil:",options:["Ketua memutuskan sendiri secara diam-diam tanpa bertanya kepada siapa pun, lalu mengumumkannya di hari terakhir","Kumpulkan pilihan & kriteria bersama, dengarkan semua, putuskan berdasarkan kesepakatan atau cara yang disepakati (voting, dll.)","Pendapat anggota yang paling lantang bersuara yang menang, karena suara yang kecil biasanya kurang meyakinkan"],answer:1,explain:"Keputusan bersama yang prosesnya jelas dan adil lebih mudah didukung dan dijalankan.",hint:"Apa yang membuat keputusan kelompok terasa adil?"},
{n:18,type:"mcq",micro:"Keputusan dan nilai pribadi",q:"Dua orang menghadapi keputusan yang sama bisa memilih berbeda karena...",options:["Salah satu dari mereka pasti salah memilih, karena keputusan yang benar untuk satu keadaan hanya ada satu","Keputusan tidak boleh berbeda antara dua orang, sehingga yang memilih berbeda sebaiknya mengikuti pilihan lainnya","Mereka menimbang kriteria dengan bobot berbeda sesuai nilai & keadaan masing-masing"],answer:2,explain:"Tidak ada satu jawaban 'benar' untuk banyak keputusan pribadi. Yang penting: pilihan sesuai dengan apa yang kamu anggap penting.",hint:"Apakah 'terbaik' sama untuk semua orang?"},
{n:19,type:"mcq",micro:"Keputusan yang jujur pada diri sendiri",q:"Kamu sudah 'memutuskan' ingin A, lalu mencari alasan untuk membenarkannya dan mengabaikan kelemahannya. Ini...",options:["Bukan mengambil keputusan yang sebenarnya — itu membenarkan pilihan yang sudah ada; periksa juga sisi buruk A dan sisi baik pilihan lain","Cara yang efisien","Selalu menghasilkan pilihan terbaik"],answer:0,explain:"Keputusan sejati terbuka pada temuan bahwa pilihan awalmu ternyata bukan yang terbaik.",hint:"Apakah kamu benar-benar menimbang, atau sudah tahu jawaban yang kamu mau?"},
{n:20,type:"open",micro:"Menstruktur sebuah keputusan",q:"Kamu punya waktu untuk satu kegiatan setelah sekolah: (a) klub olahraga, (b) les tambahan, (c) membantu usaha keluarga, (d) istirahat & bermain. Struktur keputusannya: tulis 3–4 kriteria yang penting bagimu, dan untuk tiap pilihan tuliskan satu akibat positif dan satu akibat negatif.",explain:"Jawaban baik menyebut kriteria yang benar-benar pribadi dan akibat dua sisi untuk tiap pilihan.",hint:"Kriteria = apa yang kamu pedulikan; akibat = apa yang terjadi kalau memilih itu.",sample:"Kriteria: kesehatan & kebugaran, nilai sekolah, membantu keluarga/tanggung jawab, waktu istirahat/kesenangan. (a) Klub olahraga: + bugar & teman baru; − lelah, kurang waktu belajar. (b) Les: + nilai naik; − capek, biaya, kurang gerak. (c) Bantu usaha: + belajar tanggung jawab & dapat uang saku; − sedikit waktu untuk hal lain. (d) Istirahat: + pulih & senang; − tidak ada kemajuan pada tujuan lain. Setelah menimbang, pilih yang paling seimbang dengan keadaanku sekarang (mis. kalau nilai sedang turun, prioritaskan b sementara)."},
{n:21,type:"mcq",micro:"Daftar pro dan kontra",q:"Daftar 'pro & kontra' untuk sebuah pilihan berguna, tapi kelemahannya:",options:["Selalu memberi jawaban salah","Tidak menunjukkan bahwa sebagian pro/kontra jauh lebih penting daripada yang lain — jumlah poin bukan segalanya","Terlalu rumit"],answer:1,explain:"5 pro kecil bisa kalah oleh 1 kontra besar. Menimbang bobot tiap poin lebih baik daripada menghitungnya.",hint:"Apakah '5 keuntungan kecil' otomatis mengalahkan '1 kerugian besar'?"},
{n:22,type:"mcq",micro:"Matriks keputusan",q:"'Matriks keputusan' adalah tabel dengan...",options:["Daftar nama","Gambar situasi","Pilihan di baris, kriteria di kolom, skor di tiap sel — untuk membandingkan secara sistematis"],answer:2,explain:"Matriks membuat perbandingan terlihat: tiap pilihan dinilai pada tiap kriteria, lalu dijumlahkan (sering dengan bobot).",hint:"Bagaimana membandingkan 4 pilihan pada 4 kriteria sekaligus?"},
{n:23,type:"mcq",micro:"Bobot kriteria",q:"Memberi bobot ('kesehatan × 3, biaya × 2, kesenangan × 1') berarti...",options:["Kriteria yang lebih penting bagimu berpengaruh lebih besar pada skor akhir","Semua kriteria sama","Kriteria berbobot kecil diabaikan"],answer:0,explain:"Bobot mencerminkan bahwa tidak semua hal sama pentingnya untukmu.",hint:"Apakah 'hemat sedikit uang' sepenting 'menjaga kesehatan'?"},
{n:24,type:"mcq",micro:"Kriteria wajib",q:"Sebagian kriteria bersifat 'lolos/gagal' — misalnya 'aku harus bisa pulang sebelum magrib'. Pilihan yang gagal kriteria wajib...",options:["Diberi bonus","Langsung gugur, tak peduli skornya di kriteria lain","Tetap bisa menang kalau seru"],answer:1,explain:"Syarat mutlak menyaring dulu; hanya pilihan yang lolos semua syarat mutlak yang dinilai lebih lanjut.",hint:"Bisakah pilihan yang membuatmu pulang larut menang hanya karena murah?"},
{n:25,type:"classify",micro:"Fakta, kriteria, atau akibat",q:"Untuk keputusan 'memilih ponsel bekas', kelompokkan tiap hal sebagai 'Fakta', 'Kriteria', atau 'Akibat yang diperkirakan'.",items:["Harganya Rp900.000","Aku ingin baterai tahan seharian","Kalau beli yang ini, tabunganku tersisa Rp100.000","Layarnya retak kecil di pojok"],groups:["Fakta","Kriteria","Akibat yang diperkirakan"],answer:{"Fakta":["Harganya Rp900.000","Layarnya retak kecil di pojok"],"Kriteria":["Aku ingin baterai tahan seharian"],"Akibat yang diperkirakan":["Kalau beli yang ini, tabunganku tersisa Rp100.000"]},explain:"Fakta = yang bisa diperiksa sekarang; kriteria = apa yang kamu pedulikan; akibat = yang terjadi setelah memilih.",hint:"Bisa dicek sekarang? Hal yang kupedulikan? Konsekuensi memilih?"},
{n:26,type:"mcq",micro:"Ketidakpastian dalam keputusan",q:"Kamu tidak yakin apakah klub robotik akan tetap berjalan tahun depan. Cara menghadapi ketidakpastian ini:",options:["Anggap pasti berjalan","Anggap pasti bubar","Pertimbangkan kedua kemungkinan (berjalan / bubar) dan seberapa buruk akibatnya di tiap kasus; utamakan pilihan yang tetap oke di kedua skenario"],answer:2,explain:"Untuk keputusan dengan hal tak pasti, pikirkan beberapa skenario dan cari pilihan yang cukup baik di berbagai kemungkinan.",hint:"Pilihan mana yang tidak terlalu buruk baik kalau klub jalan maupun kalau bubar?"},
{n:27,type:"mcq",micro:"Kemungkinan × dampak",q:"Menilai risiko sebuah pilihan berarti mempertimbangkan...",options:["Seberapa MUNGKIN hal buruk terjadi DAN seberapa BESAR dampaknya kalau terjadi","Hanya seberapa mungkin hal buruk itu terjadi, tanpa perlu memikirkan seberapa parah akibatnya nanti","Hanya seberapa besar dampaknya kalau terjadi, tanpa perlu memikirkan seberapa mungkin hal itu terjadi"],answer:0,explain:"Risiko kecil-mungkin-tapi-dampak-besar (kehilangan seluruh tabungan) berbeda dari sering-terjadi-tapi-dampak-kecil (kehabisan pulsa).",hint:"Dua hal apa yang membuat sebuah risiko 'serius'?"},
{n:28,type:"mcq",micro:"Pohon keputusan sederhana",q:"'Pohon keputusan' menggambarkan...",options:["Daftar keputusan masa lalu yang sudah pernah diambil, disusun dari yang paling lama sampai yang paling baru, untuk dikenang kembali oleh seluruh anggota kelompok","Pilihan bercabang: 'kalau pilih A lalu terjadi X → hasil 1; kalau terjadi Y → hasil 2', membantu melihat semua kemungkinan jalur","Jenis pohon yang tumbuh di taman sekolah, yang digambar bercabang-cabang untuk dipelajari dalam pelajaran sains dan tidak berkaitan dengan memilih tindakan"],answer:1,explain:"Pohon keputusan berguna saat sebuah pilihan diikuti kejadian tak pasti yang menghasilkan hasil berbeda.",hint:"Bagaimana menggambarkan 'pilih A, lalu tergantung cuaca hasilnya bisa begini atau begitu'?"},
{n:29,type:"tf",micro:"Keputusan bertahap",q:"Benar atau Salah: Untuk keputusan besar yang tidak mendesak, kadang bijak membuatnya bertahap — ambil langkah kecil yang bisa dibatalkan, pelajari hasilnya, baru berkomitmen penuh.",answer:true,explain:"Keputusan bertahap mengubah taruhan besar menjadi serangkaian taruhan kecil yang lebih aman, sambil mengumpulkan informasi.",hint:"Bisakah kamu 'mencoba' sebelum 'memutuskan sepenuhnya'?"},
{n:30,type:"order",micro:"Memakai matriks keputusan pribadi",q:"Urutkan langkah memakai matriks keputusan.",items:["Daftar pilihan dan kriteria (beri bobot), tentukan syarat wajib bila ada","Buang pilihan yang gagal syarat wajib","Beri skor tiap pilihan pada tiap kriteria, kalikan bobot, jumlahkan","Tinjau: kalau ada yang hampir seri, pakai pertimbangan/intuisi berdasar pengalaman"],answer:[0,1,2,3],explain:"Pilihan & kriteria & bobot → filter wajib → skor berbobot → tinjau & putuskan.",hint:"Kamu butuh kriteria sebelum bisa memberi skor."},
{n:31,type:"mcq",micro:"Skor yang jujur",q:"Godaan yang merusak matriks keputusan:",options:["Menilai setiap pilihan berdasarkan perkiraan terbaik yang kamu punya dan mencatat alasannya dengan jujur","Memberi skor rendah ke semua pilihan supaya hasil akhirnya terlihat ketat dan tidak ada yang merasa menang","Diam-diam memberi skor tinggi ke pilihan yang sudah kamu inginkan agar 'menang'"],answer:2,explain:"Matriks hanya berguna kalau skornya jujur. Kalau kamu menyetel skor untuk hasil yang kamu mau, alatnya sia-sia.",hint:"Untuk apa memakai alat kalau kamu memaksa hasilnya?"},
{n:32,type:"mcq",micro:"Kapan matriks berlebihan",q:"Untuk keputusan kecil sehari-hari, membuat matriks formal...",options:["Berlebihan — perbandingan cepat 2 kriteria di kepala cukup","Selalu wajib","Satu-satunya cara"],answer:0,explain:"Alat formal untuk keputusan besar/rumit; untuk yang kecil, pertimbangan cepat lebih efisien.",hint:"Apakah memilih menu makan siang butuh tabel skor?"},
{n:33,type:"mcq",micro:"Informasi yang cukup",q:"Berapa banyak informasi yang perlu dikumpulkan sebelum memutuskan bergantung pada...",options:["Tidak butuh informasi apa pun, karena keputusan yang baik selalu bisa diambil dari perasaan pertama saja","Pentingnya keputusan & seberapa sulit dibatalkan — besar & permanen butuh lebih banyak; kecil & reversibel butuh sedikit","Selalu sebanyak mungkin tanpa batas, bahkan untuk keputusan kecil yang mudah dibatalkan keesokan harinya"],answer:1,explain:"Sesuaikan usaha mengumpulkan info dengan taruhan keputusan.",hint:"Apakah memilih tempat duduk butuh riset sebanyak memilih sekolah?"},
{n:34,type:"mcq",micro:"Keputusan 'cukup baik' vs 'sempurna'",q:"Menunggu pilihan yang sempurna di semua kriteria sering...",options:["Adalah satu-satunya cara bijak untuk memutuskan, karena pilihan yang kurang sempurna pasti membawa penyesalan","Menjamin kita mendapat hasil yang terbaik, karena makin lama menunggu pilihan yang muncul makin sempurna","Membuat kita tidak pernah memutuskan; pilihan 'cukup baik' yang bisa diambil sekarang biasanya lebih berharga"],answer:2,explain:"Pilihan sempurna jarang ada. 'Cukup baik dan bisa dijalankan' biasanya mengalahkan menunggu tanpa akhir.",hint:"Mana lebih baik: keputusan 85% sekarang, atau keputusan 100% yang tak pernah diambil?"},
{n:35,type:"mcq",micro:"Kriteria yang terlewat",q:"Setelah matriks memilih A, kamu sadar 'aku lupa memasukkan: apakah temanku ikut'. Respons:",options:["Tambahkan kriteria itu (dengan bobot yang jujur) dan hitung ulang — matriks awal melewatkan sesuatu yang penting","Abaikan saja kriteria tambahan itu, karena matriks sudah memutuskan dan hasil hitungan tidak boleh diubah lagi","Buang seluruh matriks dan putuskan dengan melempar koin saja, karena penilaian yang tadi sudah tidak berguna"],answer:0,explain:"Matriks sebaik kriteria yang dimasukkan. Kalau ada yang penting terlewat, tambahkan dan nilai ulang.",hint:"Apakah hasil matriks lebih penting daripada faktor nyata yang terlewat?"},
{n:36,type:"mcq",micro:"Keputusan dan emosi",q:"Perasaan kuat (sangat bersemangat / sangat takut) saat mengambil keputusan sebaiknya...",options:["Menjadi satu-satunya penentu","Diperhatikan sebagai informasi, tapi keputusan besar sebaiknya tidak diambil di puncak emosi — beri jeda","Diabaikan total"],answer:1,explain:"Emosi memberi petunjuk tentang apa yang penting, tapi di puncaknya bisa mempersempit pemikiran. Jeda membantu.",hint:"Apakah keputusan yang diambil saat sangat marah biasanya keputusan terbaik?"},
{n:37,type:"tf",micro:"Keputusan yang sama bisa punya jawaban berbeda seiring waktu",q:"Benar atau Salah: Kalau sebuah pilihan tepat untukmu tahun lalu, ia pasti masih pilihan yang tepat sekarang, apa pun yang berubah.",answer:false,explain:"Keadaan, tujuan, dan informasimu bisa berubah, jadi pilihan yang dulu tepat belum tentu tepat sekarang. Meninjau kembali keputusan lama saat keadaan berubah itu wajar, bukan tanda plin-plan.",hint:"Apakah pilihan sekolah untuk anak kelas 3 sama dengan untuk anak kelas 9?"},
{n:38,type:"mcq",micro:"Meminta pendapat tanpa menyerahkan keputusan",q:"Bertanya ke beberapa orang sebelum memutuskan berguna, asalkan...",options:["Kamu selalu mengikuti pendapat mayoritas yang kamu tanyai, karena suara terbanyak pasti lebih benar","Kamu mengikuti orang yang paling percaya diri saat berbicara, karena orang seperti itu pasti paling tahu","Kamu tetap yang menimbang dan memutuskan — pendapat mereka adalah masukan, bukan perintah"],answer:2,explain:"Masukan memperkaya pertimbangan; tapi karena kamu yang menanggung akibatnya, keputusan tetap milikmu.",hint:"Siapa yang akan hidup dengan hasil keputusan ini?"},
{n:39,type:"mcq",micro:"Keputusan kelompok yang macet",q:"Kelompok tidak bisa sepakat memilih. Cara yang membantu:",options:["Sepakati dulu KRITERIA bersama, nilai pilihan bersama, lalu putuskan berdasarkan hasil (atau cara yang disepakati seperti voting)","Debat terus sampai satu pihak menyerah","Batalkan kegiatan"],answer:0,explain:"Menyepakati kriteria SEBELUM menilai mengubah 'aku vs kamu' menjadi 'mari lihat mana yang paling memenuhi hal yang kita sepakati penting'.",hint:"Apa yang mengurangi perdebatan berbasis ego?"},
{n:40,type:"open",micro:"Membuat matriks keputusan",q:"Keputusan: memilih SATU dari 3 ekskul — (A) basket, (B) jurnalistik, (C) robotik. Buat matriks: 3–4 kriteria dengan bobot, skor 1–5 tiap ekskul, total, dan kesimpulan termasuk apa yang kamu korbankan (biaya peluang).",explain:"Jawaban baik: kriteria pribadi berbobot, skor masuk akal, perhitungan benar, dan menyebut biaya peluang + catatan risiko dari skor rendah.",hint:"Perhatikan kriteria dengan skor sangat rendah pada pemenang — itu risiko yang perlu ditimbang terpisah.",sample:"Kriteria (bobot): sesuai minat (×3), kembangkan keterampilan berguna (×2), cocok jadwal & tenaga (×2), ada teman/lingkungan nyaman (×1). A basket: minat 4, keterampilan 2, jadwal 3, teman 5 → 12+4+6+5 = 27. B jurnalistik: minat 3, keterampilan 5, jadwal 4, teman 3 → 9+10+8+3 = 30. C robotik: minat 5, keterampilan 5, jadwal 2, teman 2 → 15+10+4+2 = 31. Kesimpulan: C unggul tipis atas B, terutama karena minat & keterampilan; tapi skor jadwal rendah (2) berarti risiko kelelahan — perlu dicek apakah realistis. Biaya peluang: memilih C berarti melepas latihan fisik rutin (A) dan keterampilan menulis (B); bisa dikurangi dengan olahraga mandiri di akhir pekan."},
{n:41,type:"mcq",micro:"Membayangkan skenario terburuk & terbaik",q:"Sebelum keputusan besar, membayangkan 'apa hasil terburuk yang masuk akal?' dan 'apa hasil terbaik?' berguna untuk...",options:["Hanya hasil yang terbaik saja yang penting dipikirkan, sedangkan hasil terburuk tidak perlu dibayangkan","Menilai apakah kamu bisa menanggung yang terburuk, dan apakah yang terbaik sepadan dengan usahanya","Membuat dirimu cemas tanpa guna, karena hasil yang akan terjadi tidak bisa dibayangkan sebelumnya"],answer:1,explain:"Kalau kamu bisa hidup dengan hasil terburuk yang realistis, keputusan berisiko jadi lebih aman diambil.",hint:"Apa hal terburuk yang bisa terjadi, dan bisakah kamu menanggungnya?"},
{n:42,type:"mcq",micro:"Keputusan yang mudah dibatalkan",q:"Aturan praktis: untuk keputusan yang mudah dibatalkan, ...",options:["Perlakukan sama seperti keputusan permanen, dengan menimbang berhari-hari dan mengumpulkan sebanyak mungkin data","Jangan pernah diputuskan sama sekali, biarkan saja berjalan sampai keadaan yang akhirnya memilih untukmu","Putuskan cepat dan pelajari dari hasilnya; simpan energi berpikir untuk keputusan yang sulit dibalik"],answer:2,explain:"Menghabiskan waktu lama pada keputusan reversibel adalah pemborosan; cukup coba dan sesuaikan.",hint:"Kalau salah pun kamu bisa kembali besok, seberapa lama perlu menimbang?"},
{n:43,type:"mcq",micro:"Nilai harapan sederhana",q:"Pilihan A: pasti dapat 10 poin. Pilihan B: 50% dapat 30 poin, 50% dapat 0. 'Rata-rata jangka panjang' B adalah...",options:["15 poin (0,5×30 + 0,5×0)","30 poin","0 poin"],answer:0,explain:"Nilai harapan = jumlah dari (peluang × hasil). B rata-rata 15, lebih tinggi dari A (10) — tapi B lebih berisiko.",hint:"Kalikan tiap hasil dengan peluangnya, lalu jumlahkan."},
{n:44,type:"mcq",micro:"Rata-rata bukan segalanya",q:"Meski B (contoh sebelumnya) punya rata-rata lebih tinggi, kamu mungkin tetap memilih A kalau...",options:["Kamu menyukai angka genap, sehingga pilihan A terasa lebih nyaman walaupun peluangnya tidak berbeda jauh","Kamu hanya punya satu kesempatan dan BENAR-BENAR butuh minimal 10 poin — risiko dapat 0 tidak bisa ditanggung","Rata-rata selalu menang dalam setiap keadaan, sehingga keadaan pribadi seseorang tidak perlu ikut dipertimbangkan"],answer:1,explain:"Untuk keputusan sekali jalan dengan taruhan tinggi, menghindari hasil terburuk bisa lebih penting daripada rata-rata tertinggi.",hint:"Apa bedanya bermain 100 kali vs bermain sekali saja?"},
{n:45,type:"mcq",micro:"Keputusan dan komitmen",q:"Setelah menimbang dengan cukup dan memilih, terus-menerus meragukan dan mengubah pikiran...",options:["Selalu bijak","Tanda kehati-hatian yang baik","Sering merugikan — pada titik tertentu, berkomitmen dan menjalankan pilihan dengan sungguh-sungguh lebih baik daripada terus ragu"],answer:2,explain:"Ada waktu untuk menimbang dan waktu untuk berkomitmen. Keraguan tanpa akhir menghabiskan energi dan menghambat pelaksanaan.",hint:"Kapan 'hati-hati' berubah menjadi 'tidak pernah maju'?"},
{n:46,type:"mcq",micro:"Menetapkan titik tinjau",q:"Saat berkomitmen pada pilihan yang tidak pasti, berguna menetapkan...",options:["Kapan & berdasarkan apa kamu akan meninjau ulang ('kalau setelah 1 bulan aku masih benci les ini, aku berhenti')","Bahwa keputusan itu tidak boleh ditinjau ulang selamanya, supaya kamu terlihat konsisten di mata semua orang","Bahwa kamu akan berhenti kapan saja terasa berat, tanpa perlu menunggu atau mencatat alasannya terlebih dahulu"],answer:0,explain:"Titik tinjau yang ditetapkan di depan mencegah baik 'menyerah terlalu cepat' maupun 'terjebak terlalu lama'.",hint:"Bagaimana kamu tahu kapan waktunya mengevaluasi ulang, tanpa berhenti di setiap kesulitan kecil?"},
{n:47,type:"order",micro:"Keputusan berisiko",q:"Urutkan langkah mengambil keputusan yang punya risiko.",items:["Daftar pilihan dan kemungkinan hasil tiap pilihan (baik & buruk)","Perkirakan seberapa mungkin & seberapa besar dampak tiap hasil","Periksa: bisakah aku menanggung hasil terburuk yang realistis?","Pilih, siapkan rencana bila hal buruk terjadi, dan tetapkan titik tinjau"],answer:[0,1,2,3],explain:"Daftar hasil → perkirakan peluang & dampak → cek daya tanggung → pilih dengan rencana cadangan & titik tinjau.",hint:"Kamu perlu tahu hasil-hasil yang mungkin sebelum bisa menilai risikonya."},
{n:48,type:"mcq",micro:"Diversifikasi keputusan",q:"Alih-alih menaruh semua tabungan pada satu 'peluang', membaginya ke beberapa pilihan yang lebih aman disebut...",options:["Boros","Menyebar risiko (diversifikasi) — kalau satu gagal, tidak semua ikut hilang","Ragu-ragu"],answer:1,explain:"Untuk keputusan dengan ketidakpastian besar, tidak menaruh semua telur di satu keranjang mengurangi kemungkinan kehilangan segalanya.",hint:"Apa yang terjadi kalau satu-satunya keranjang telurmu jatuh?"},
{n:49,type:"mcq",micro:"Keputusan yang menciptakan pilihan lebih banyak",q:"Di antara dua pilihan yang setara, sering lebih baik memilih yang...",options:["Menutup semua pilihan lain","Paling membatasi","Membuka lebih banyak pilihan di masa depan (menjaga opsi tetap terbuka), terutama saat kamu tidak yakin"],answer:2,explain:"Saat masa depan tidak pasti, pilihan yang menjaga fleksibilitas sering lebih berharga.",hint:"Pilihan mana yang tidak mengunci kamu, kalau ternyata keadaan berubah?"},
{n:50,type:"mcq",micro:"Keputusan dan tanggung jawab",q:"Setelah mengambil keputusan yang ternyata kurang tepat, sikap yang matang:",options:["Akui, pelajari apa yang bisa diperbaiki dalam prosesnya, dan ambil langkah untuk memperbaiki keadaan — bukan menyembunyikan atau menyalahkan keadaan sepenuhnya","Salahkan orang yang memberi masukan kepadamu, karena keputusan itu sebenarnya berasal dari saran mereka, lalu sembunyikan kekeliruan itu dari orang lain sebisanya","Pura-pura keputusanmu tetap benar supaya orang lain tetap percaya kepadamu, dan jangan pernah membahas ataupun memperbaikinya lagi di kemudian hari nanti"],answer:0,explain:"Bertanggung jawab atas keputusan sendiri — termasuk yang kurang tepat — membangun kepercayaan dan penilaian yang lebih baik.",hint:"Apa yang membedakan orang yang belajar dari keputusan buruk dari yang mengulanginya?"},
{n:51,type:"open",micro:"Keputusan berisiko dengan rencana cadangan",q:"Keputusan: ikut lomba tingkat kota yang jadwalnya bentrok dengan pekan ujian sekolah. Analisis: (1) hasil baik & buruk yang mungkin, (2) seberapa mungkin & besar dampaknya, (3) bisakah kamu menanggung yang terburuk, (4) keputusanmu + rencana bila hal buruk terjadi + titik tinjau.",explain:"Jawaban baik: memetakan hasil dua sisi, menilai peluang & dampak, memeriksa daya tanggung terhadap kasus terburuk, lalu memutuskan dengan mitigasi konkret dan titik tinjau yang jelas.",hint:"Kunci di (3): apakah ada ujian yang tidak bisa diperbaiki? Itu menentukan apakah risikonya bisa ditanggung.",sample:"(1) Baik: pengalaman berharga, mungkin menang, relasi baru. Buruk: nilai ujian turun karena kurang persiapan; kelelahan; kalah dan merasa sia-sia. (2) Nilai turun: cukup mungkin (mungkin 50%) dengan dampak sedang (bisa diperbaiki di semester berikutnya, kecuali ada ujian penentu). Kelelahan: mungkin, dampak kecil-sedang. (3) Kalau tidak ada ujian penentu kelulusan minggu itu, dampak terburuk (nilai beberapa mapel turun sedikit) bisa ditanggung dan diperbaiki. (4) Keputusan: ikut, TAPI: minta jadwal ujian susulan untuk mapel yang bentrok langsung dengan hari lomba (kalau sekolah izinkan); buat jadwal belajar padat 2 minggu sebelum, fokus mapel terberat; batasi latihan lomba maksimal 1 jam/hari di pekan ujian. Rencana bila buruk: kalau simulasi/try-out sepekan sebelum ujian anjlok drastis, mundur dari lomba. Titik tinjau: hasil try-out H-7."},
{n:52,type:"mcq",micro:"Keputusan yang dipengaruhi cara pertanyaan diajukan",q:"'Operasi ini punya tingkat keberhasilan 90%' vs 'operasi ini punya tingkat kegagalan 10%' — keduanya fakta yang sama, tapi...",options:["Yang kedua pasti lebih benar karena menyebut risiko secara terus terang, sedangkan yang pertama hanya membujuk","Cara membingkainya bisa membuat orang merasa berbeda; sadari framing dan lihat angka mentahnya","Yang pertama pasti lebih benar karena menyebut hal yang baik, sehingga angka kegagalannya tidak perlu dilihat"],answer:1,explain:"'Efek framing': informasi yang sama terasa berbeda tergantung penyajiannya. Ubah ke bentuk lain untuk memeriksa.",hint:"Apakah '90% berhasil' dan '10% gagal' adalah fakta yang sama?"},
{n:53,type:"tf",micro:"Keputusan tergesa vs terlalu lama",q:"Benar atau Salah: Ada dua kesalahan berlawanan dalam mengambil keputusan — memutuskan terlalu cepat tanpa berpikir, dan menunda terlalu lama sehingga kesempatan hilang atau energi habis.",answer:true,explain:"Tujuannya menemukan titik tengah: cukup berpikir untuk keputusan yang baik, cukup cepat untuk tetap bertindak.",hint:"Apakah 'langsung terjun' dan 'tidak pernah memutuskan' sama-sama bermasalah?"},
{n:54,type:"mcq",micro:"Menghindari keputusan dari rasa takut ketinggalan",q:"'Semua temanku ikut, jadi aku harus ikut juga' sebagai satu-satunya alasan...",options:["Selalu merupakan alasan yang cukup kuat, karena pilihan banyak orang pasti pilihan yang paling tepat bagimu","Tidak pernah relevan dalam keputusan apa pun, sehingga pilihan teman tidak boleh dipertimbangkan sama sekali","Lemah — periksa apakah pilihan itu benar-benar sesuai kriteria & keadaanmu, bukan hanya karena takut berbeda"],answer:2,explain:"Tekanan sosial dan rasa takut ketinggalan (FOMO) bisa mendorong keputusan yang tidak sesuai dengan kepentinganmu sendiri.",hint:"Apakah kamu memilih ini karena cocok untukmu, atau karena takut jadi satu-satunya yang tidak?"},
{n:55,type:"mcq",micro:"Keputusan dan biaya hangus",q:"Kamu sudah bayar les Rp500.000 dan baru sadar les itu tidak cocok. Meneruskannya 'karena sudah bayar' adalah...",options:["Kesalahan biaya hangus — uang itu sudah tidak kembali apa pun pilihanmu; keputusan sekarang harus berdasarkan 'apa yang terbaik dari titik ini ke depan'","Keputusan yang bijak","Cara menghemat"],answer:0,explain:"Uang atau waktu yang sudah dikeluarkan tidak bisa kembali. Keputusan ke depan tidak boleh disandera olehnya.",hint:"Apakah 'sudah bayar' membuat waktu yang terbuang jadi lebih berharga?"},
{n:56,type:"mcq",micro:"Keputusan bersama yang adil",q:"Selain hasilnya, sebuah keputusan kelompok terasa adil kalau...",options:["Ketua yang memutuskan dengan cepat tanpa banyak bertanya, sehingga tidak ada waktu terbuang untuk berdebat","Prosesnya transparan, semua suara didengar, dan kriteria disepakati bersama — meski hasil akhirnya tidak semua orang setuju","Semua orang mendapat apa yang mereka inginkan tanpa kecuali, sehingga tidak ada satu pun yang kecewa kemudian"],answer:1,explain:"Keadilan prosedural (proses yang adil) membuat orang lebih menerima hasil, bahkan saat pilihan mereka tidak menang.",hint:"Mengapa orang bisa menerima kekalahan dalam voting yang jujur?"},
{n:57,type:"tf",micro:"Keputusan yang baik bisa berhasil buruk",q:"Benar atau Salah: Kalau sebuah keputusan berujung hasil buruk, itu selalu berarti keputusannya diambil dengan proses yang salah.",answer:false,explain:"Tidak selalu. Keputusan dengan proses baik (informasi cukup, pertimbangan matang) bisa tetap berujung buruk karena keberuntungan/faktor tak terduga — dan sebaliknya. Nilai keputusan dari prosesnya, bukan hanya hasilnya.",hint:"Kalau kamu menyeberang saat lampu hijau lalu ada mobil menerobos, apakah keputusanmu menyeberang itu 'salah'?"},
{n:58,type:"mcq",micro:"Keputusan dan informasi yang berubah",q:"Setelah memutuskan A, muncul informasi baru penting yang seharusnya mengubah pilihan. Sikap yang tepat:",options:["Pertahankan pilihan A apa pun yang terjadi, karena mengubah keputusan menunjukkan bahwa kita orang yang plin-plan","Selalu berubah setiap ada informasi baru sekecil apa pun, walaupun informasi itu tidak memengaruhi pilihan","Tinjau ulang berdasarkan informasi baru — mengubah keputusan karena fakta baru adalah kekuatan, bukan kelemahan"],answer:2,explain:"Berkomitmen bukan berarti keras kepala. Informasi baru yang signifikan adalah alasan sah untuk meninjau kembali.",hint:"Apakah tetap di jalan yang salah demi 'konsisten' itu bijak?"},
{n:59,type:"mcq",micro:"Menuliskan alasan keputusan",q:"Mencatat 'aku memilih A karena X, Y, Z; asumsiku adalah W' saat mengambil keputusan besar berguna karena...",options:["Nanti kamu bisa memeriksa apakah alasannya masih berlaku, dan belajar dari keputusan (bukan sekadar mengingat hasilnya secara samar)","Membuang waktu","Hanya untuk keputusan orang dewasa"],answer:0,explain:"Catatan keputusan memungkinkan refleksi yang jujur: 'apakah aku salah menimbang, atau hanya sial?'",hint:"Bagaimana kamu belajar dari keputusan tanpa mengingat mengapa kamu membuatnya?"},
{n:60,type:"open",micro:"Keputusan dengan ketidakpastian & framing",q:"Keputusan: menabung uang Rp300.000 (aman, bertambah sedikit) ATAU memakainya sebagai modal jualan kecil (bisa untung, bisa rugi sebagian). Analisis: (1) hasil & peluang kasar tiap pilihan, (2) periksa framing — tulis ulang pilihan 'jualan' dari sisi kerugian, (3) bisakah kamu menanggung kerugian terburuk, (4) keputusanmu + alasan + apa yang membuatmu meninjau ulang.",explain:"Jawaban baik: memperkirakan hasil & peluang, menerapkan pemeriksaan framing (menulis ulang dari sisi rugi), menilai daya tanggung, dan memutuskan dengan pembatasan risiko (modal separuh) + titik tinjau.",hint:"Perhatikan bagian (2) — apakah 'peluang untung' dan 'peluang rugi' terasa berbeda saat kamu menuliskannya dengan cara yang berbeda?",sample:"(1) Menabung: hampir pasti tetap ~Rp300.000 (+ bunga kecil). Jualan: perkiraan kasar — 40% untung Rp150.000+, 35% impas, 25% rugi Rp100.000–200.000 (modal & stok tak laku). (2) Framing kerugian: 'ada kemungkinan 1 dari 4 aku kehilangan sepertiga sampai dua pertiga modalku dan hanya tersisa Rp100.000–200.000'. (3) Kalau Rp300.000 itu bukan dana daruratku dan aku masih punya kebutuhan tercukupi, kehilangan sebagian bisa ditanggung sebagai 'biaya belajar'. (4) Keputusan: coba jualan dengan modal SETENGAH (Rp150.000) dulu, sisanya ditabung — ini membatasi kerugian terburuk sambil tetap belajar. Tinjau ulang setelah 1 bulan: kalau rugi lebih dari Rp75.000 atau tidak menikmati prosesnya, hentikan dan tabung sisanya."},
{n:61,type:"mcq",micro:"Bias konfirmasi dalam keputusan",q:"Kamu sudah condong ke pilihan A, lalu hanya mencari informasi yang mendukung A dan mengabaikan yang mendukung B. Ini bias konfirmasi. Penawarnya:",options:["Jangan mencari informasi apa pun lagi, karena makin banyak informasi makin membuat pilihanmu membingungkan","Sengaja cari informasi & argumen TERKUAT untuk pilihan yang tidak kamu sukai, dan pertimbangkan dengan serius","Ikuti saja kecondonganmu sejak awal, karena perasaan pertama biasanya sudah menunjukkan pilihan yang paling tepat"],answer:1,explain:"Melawan bias konfirmasi berarti aktif mencari bukti yang bisa membuktikanmu salah.",hint:"Apa argumen terbaik untuk pilihan yang TIDAK kamu sukai?"},
{n:62,type:"mcq",micro:"Penjangkaran (anchoring)",q:"Harga awal yang disebut penjual (Rp500.000) memengaruhi berapa 'wajar' menurutmu, meski barangnya sebenarnya bernilai Rp200.000. Ini 'penjangkaran'. Cara mengurangi:",options:["Percaya saja pada harga pertama yang disebut penjual, karena penjual pasti lebih tahu nilai barangnya daripada kamu","Selalu tawar setengah harga dari yang disebut penjual, tanpa menghitung dulu berapa nilai barang itu sebenarnya","Tentukan sendiri perkiraan nilaimu SEBELUM melihat harga yang mereka sebut, dan bandingkan dengan pilihan lain"],answer:2,explain:"Angka pertama yang kita dengar menjadi 'jangkar' yang menyeret penilaian. Membentuk penilaian sendiri lebih dulu melawannya.",hint:"Dari mana perkiraan 'harga wajar' di kepalamu berasal?"},
{n:63,type:"tf",micro:"Terlalu banyak pilihan bisa melumpuhkan",q:"Benar atau Salah: Dihadapkan pada terlalu banyak pilihan tanpa disaring, orang sering kewalahan, menunda, atau akhirnya memilih asal.",answer:true,explain:"Menyaring dulu menjadi 3–5 kandidat kuat sering menghasilkan keputusan yang lebih baik daripada menghadapi 30 pilihan sekaligus.",hint:"Lebih mudah memilih di antara 3 atau 30?"},
{n:64,type:"mcq",micro:"Bias status quo",q:"Kecenderungan memilih 'biarkan seperti sekarang' hanya karena itu yang sudah ada disebut bias status quo. Menyeimbangkannya:",options:["Perlakukan 'tidak berubah' sebagai satu pilihan yang juga dinilai dengan kriteria yang sama, bukan default otomatis","Selalu ubah sesuatu","Jangan pernah ubah apa pun"],answer:0,explain:"'Tetap seperti sekarang' harus bersaing adil dengan pilihan lain.",hint:"Apakah pilihan lama menang karena terbaik, atau karena paling tidak butuh usaha?"},
{n:65,type:"mcq",micro:"Keputusan kelompok: pemikiran kelompok",q:"'Pemikiran kelompok' (groupthink) terjadi ketika...",options:["Setiap orang berpikir sendiri-sendiri secara bebas lalu menyampaikan keberatannya, sehingga keputusan menjadi matang","Keinginan untuk sepakat dan tidak berkonflik membuat kelompok mengabaikan keberatan dan alternatif — keputusan terlihat bulat padahal rapuh","Kelompok berdebat terlalu banyak sehingga tidak ada yang sepakat, dan keputusan akhirnya tidak pernah diambil"],answer:1,explain:"Groupthink menghasilkan keputusan buruk karena kritik ditekan. Penawarnya: sengaja tunjuk 'penantang', minta keberatan, kumpulkan pendapat anonim.",hint:"Apa yang terjadi kalau tidak ada yang berani mengatakan 'aku tidak setuju'?"},
{n:66,type:"tf",micro:"Diam bukan berarti setuju",q:"Benar atau Salah: Dalam keputusan kelompok, tidak adanya bantahan tidak selalu berarti semua setuju — sebagian orang mungkin segan bicara.",answer:true,explain:"Meminta pendapat tiap orang secara aktif (atau lewat tulisan anonim) mengungkap keberatan yang tidak terucap.",hint:"Mengapa seseorang mungkin diam meski tidak setuju?"},
{n:67,type:"mcq",micro:"Keputusan etis",q:"Beberapa keputusan bukan soal 'mana yang paling menguntungkan aku' tapi soal 'mana yang benar'. Untuk keputusan etis, pertanyaan yang membantu:",options:["Mana yang paling cepat selesai dan paling mudah dijalankan oleh dirimu sendiri? Mana yang paling murah? Mana yang paling banyak memberi keuntungan bagiku sendiri?","Mana yang paling kecil kemungkinan ketahuan orang lain? Mana yang bisa kusembunyikan paling lama? Mana yang tidak membuat orang lain bertanya-tanya padaku?","Apakah ini jujur? Adil bagi semua yang terdampak? Bagaimana perasaanku kalau ini diketahui semua orang? Apakah aku ingin diperlakukan begini?"],answer:2,explain:"Keputusan etis mempertimbangkan kejujuran, keadilan, dampak pada orang lain, dan apakah kita nyaman kalau pilihan itu terbuka untuk umum.",hint:"Bukan 'apa yang bisa kulakukan', tapi 'apa yang seharusnya kulakukan'."},
{n:68,type:"mcq",micro:"Keputusan yang menguntungkan diri tapi merugikan bersama",q:"Kalau semua orang membuat keputusan 'menyerobot antre karena buru-buru', hasilnya...",options:["Kekacauan yang merugikan semua, termasuk si penyerobot pada akhirnya — sebagian keputusan harus mempertimbangkan 'bagaimana kalau semua orang melakukan ini'","Menguntungkan orang yang paling cepat menyerobot, sehingga semua orang sebaiknya mengikuti caranya supaya sama-sama maju dan tidak perlu menunggu giliran lagi","Tidak berpengaruh pada siapa pun, karena antrean hanyalah kebiasaan semata dan tidak ada akibat nyata bagi orang lain, baik yang di depan maupun di belakang"],answer:0,explain:"Uji 'bagaimana kalau semua orang melakukan ini' membantu mengenali keputusan yang tampak menguntungkan pribadi tapi merusak bila umum.",hint:"Apa jadinya kalau setiap orang di antrean berpikir seperti si penyerobot?"},
{n:69,type:"mcq",micro:"Keputusan dan orang yang tidak hadir",q:"Keputusan kelas dibuat saat 5 siswa tidak masuk. Sikap yang adil:",options:["Batalkan semua keputusan yang sudah dibuat dan jangan membuat keputusan apa pun sampai seluruh siswa hadir kembali","Kalau keputusan memengaruhi mereka secara signifikan, tunda hal yang bisa ditunda, atau cari cara meminta masukan mereka","Putuskan saja tanpa menunggu, karena salah mereka sendiri tidak masuk dan pendapat mereka tidak perlu didengar"],answer:1,explain:"Keputusan yang berdampak besar sebaiknya melibatkan semua yang terdampak, termasuk yang kebetulan tidak hadir.",hint:"Bagaimana perasaanmu kalau keputusan besar tentangmu dibuat saat kamu sakit?"},
{n:70,type:"order",micro:"Melawan bias saat memutuskan",q:"Urutkan langkah memeriksa keputusan penting terhadap bias umum.",items:["Tuliskan pilihanmu & alasannya, termasuk asumsi","Cari argumen terkuat untuk pilihan lain (lawan bias konfirmasi)","Periksa: apakah aku terpengaruh angka/pilihan pertama (jangkar), atau memilih 'yang sudah ada' hanya karena mudah (status quo)?","Kalau keputusan kelompok: minta keberatan secara aktif/anonim (lawan groupthink)"],answer:[0,1,2,3],explain:"Tulis alasan → cari argumen lawan → cek jangkar & status quo → (kelompok) gali keberatan.",hint:"Kamu perlu alasanmu tertulis dulu untuk bisa mengujinya."},
{n:71,type:"mcq",micro:"Keputusan yang 'terasa benar' tapi keliru",q:"Intuisi ('ini terasa tepat') paling bisa dipercaya ketika...",options:["Selalu bisa dipercaya dalam situasi apa pun, termasuk situasi baru yang belum pernah kamu alami, karena intuisi tidak pernah salah dan tidak perlu diperiksa","Tidak pernah bisa dipercaya sama sekali, bahkan oleh orang yang berpengalaman puluhan tahun, sehingga perasaan yang muncul harus diabaikan dalam semua keputusan","Kamu punya banyak pengalaman nyata & umpan balik di jenis situasi itu; kurang bisa dipercaya di situasi baru yang belum pernah kamu alami"],answer:2,explain:"Intuisi adalah pola dari pengalaman. Ia kuat di bidang yang sudah kamu kuasai, lemah di hal yang baru.",hint:"Apakah 'firasat'-mu tentang catur lebih bisa dipercaya kalau kamu sudah bermain 1000 kali atau baru belajar?"},
{n:72,type:"mcq",micro:"Keputusan cepat yang berulang",q:"Untuk keputusan kecil yang berulang setiap hari (apa sarapan, kapan mulai belajar), cara menghemat energi keputusan:",options:["Buat aturan/kebiasaan default sekali, lalu jalankan otomatis — sisakan energi berpikir untuk keputusan yang benar-benar penting","Timbang dengan serius setiap hari seperti keputusan besar, supaya tidak ada pilihan kecil yang dilewatkan begitu saja","Serahkan semua keputusan kecil itu kepada orang lain, supaya kamu tidak pernah perlu memikirkannya sama sekali"],answer:0,explain:"Setiap keputusan menghabiskan sedikit energi mental. Merutinkan yang kecil menyisakan kapasitas untuk yang besar.",hint:"Apakah memutuskan hal yang sama tiap hari dari nol itu efisien?"},
{n:73,type:"tf",micro:"Keputusan sulit sering karena nilai yang bersaing",q:"Benar atau Salah: Kalau sebuah keputusan terasa sulit, itu selalu berarti kamu belum punya cukup informasi untuk memutuskan.",answer:false,explain:"Sering keputusan sulit bukan karena kurang informasi, melainkan karena pilihan-pilihannya bagus di hal yang berbeda dan kamu harus memutuskan mana yang lebih kamu utamakan — memilih di antara nilai yang sama-sama kamu pegang.",hint:"Kalau A lebih baik di semua kriteria, apakah keputusannya sulit?"},
{n:74,type:"mcq",micro:"Keputusan dan penyesalan yang dibayangkan",q:"Membayangkan 'pilihan mana yang akan lebih kusesali kalau tidak kuambil, 10 tahun dari sekarang' berguna untuk...",options:["Membuat cemas","Keputusan besar tentang kesempatan langka — membantu menimbang nilai jangka panjang di atas ketidaknyamanan jangka pendek","Semua keputusan sekecil apa pun"],answer:1,explain:"'Uji penyesalan' membantu untuk keputusan hidup besar, meski tidak cocok untuk keputusan sehari-hari.",hint:"Untuk kesempatan yang mungkin tidak datang lagi, sudut pandang jauh ke depan bisa menjernihkan."},
{n:75,type:"mcq",micro:"Keputusan yang dipaksa jadi biner",q:"Kamu merasa harus memilih 'A atau B'. Sebelum memutuskan, tanyakan...",options:["Tidak, dua pilihan sudah pasti semua","Lempar koin","'Apakah benar hanya ada dua pilihan? Adakah opsi C, atau cara menggabungkan A dan B, atau menunda?'"],answer:2,explain:"Banyak keputusan yang terasa 'ya/tidak' sebenarnya punya pilihan ketiga yang belum terpikir.",hint:"Apakah kelas benar-benar harus memilih 'museum ATAU pantai', atau ada tempat yang punya keduanya?"},
{n:76,type:"mcq",micro:"Keputusan di bawah pengaruh",q:"Menghindari keputusan besar saat sangat lelah, lapar, marah, atau di bawah tekanan kelompok berguna karena...",options:["Dalam kondisi itu, pemikiran menyempit dan kita lebih rentan bias & dorongan sesaat — beri jeda sampai kondisi lebih stabil","Keadaan tubuh dan perasaan tidak pernah memengaruhi keputusan, jadi kapan pun memutuskan hasilnya akan sama saja","Keputusan yang dibuat saat marah adalah yang paling jujur, sehingga justru lebih baik diambil dalam keadaan itu"],answer:0,explain:"Kondisi fisik dan emosional memengaruhi kualitas keputusan. Untuk yang penting, tunggu sampai kamu 'kembali normal'.",hint:"Apakah keputusan yang diambil saat sangat lapar atau marah biasanya keputusan terbaikmu?"},
{n:77,type:"tf",micro:"Menilai keputusan dari proses, bukan hanya hasil",q:"Benar atau Salah: Cara terbaik menilai keterampilan mengambil keputusan seseorang adalah melihat apakah prosesnya baik (informasi, pertimbangan, pengelolaan risiko), bukan sekadar apakah hasil satu keputusan kebetulan bagus.",answer:true,explain:"Hasil dipengaruhi keberuntungan. Proses yang baik meningkatkan peluang hasil baik secara konsisten dari waktu ke waktu.",hint:"Apakah menang lotre membuktikan membeli lotre itu keputusan finansial yang bijak?"},
{n:78,type:"mcq",micro:"Keputusan dan tekanan untuk segera",q:"'Kesempatan ini hanya hari ini! Putuskan sekarang!' Respons yang bijak untuk keputusan tidak sepele:",options:["Selalu tolak apa pun yang terburu-buru tanpa dipertimbangkan, karena semua tawaran mendesak pasti penipuan belaka","Curiga pada tekanan waktu buatan; keputusan penting yang baik jarang perlu diambil dalam hitungan detik — minta waktu","Selalu putuskan secepatnya agar tidak kehilangan kesempatan, karena kesempatan yang baik tidak akan datang lagi"],answer:1,explain:"Tekanan 'sekarang atau tidak sama sekali' sering taktik untuk mencegah kamu berpikir jernih. Kesempatan yang benar-benar baik biasanya memberi ruang bernapas.",hint:"Mengapa seseorang ingin kamu memutuskan sebelum sempat berpikir?"},
{n:79,type:"mcq",micro:"Keputusan yang tidak bisa dipuaskan semua orang",q:"Keputusan kelas pasti mengecewakan sebagian orang. Yang membuatnya tetap bisa diterima:",options:["Berpura-pura tidak ada seorang pun yang kecewa, supaya suasana kelas tetap tenang dan tidak ada yang protes","Membatalkan keputusan itu begitu ada yang kecewa, lalu mengulang pembahasan sampai semua orang benar-benar puas","Proses yang adil & transparan, penjelasan alasan, dan pengakuan atas pandangan yang kalah — bukan berpura-pura semua senang"],answer:2,explain:"Tidak semua keputusan bisa menyenangkan semua orang. Yang penting orang merasa didengar dan prosesnya adil.",hint:"Bagaimana orang yang pilihannya kalah tetap bisa menerima hasilnya?"},
{n:80,type:"open",micro:"Menemukan bias dalam sebuah keputusan",q:"Sebuah kelompok memutuskan: 'Kita pakai lagi tema acara tahun lalu (pesta kostum), karena tahun lalu sukses dan kita sudah punya sebagian propertinya. Ketua sudah setuju dan tidak ada yang membantah.' Identifikasi minimal 3 kemungkinan bias/kelemahan dalam keputusan ini dan bagaimana memperbaikinya.",explain:"Jawaban baik mengenali status quo/biaya hangus, bias hasil, dan groupthink/diam-bukan-setuju, lalu mengusulkan perbandingan berkriteria dan pengumpulan pendapat yang tidak menekan.",hint:"Perhatikan tiga frasa: 'pakai lagi', 'sudah punya propertinya', dan 'tidak ada yang membantah'.",sample:"(1) Bias status quo / 'sudah punya properti' → kesalahan biaya hangus: properti lama tidak boleh jadi alasan utama; nilai apakah tema ini masih yang terbaik untuk tahun ini terlepas dari properti. (2) 'Tahun lalu sukses' → mungkin bias hasil/ingatan yang bahagia; periksa APA yang membuatnya sukses (mungkin bukan temanya) dan apakah kondisinya sama. (3) 'Ketua setuju, tidak ada yang membantah' → kemungkinan groupthink / diam bukan setuju; keberatan mungkin tidak terucap karena segan. Perbaikan: kumpulkan 3–4 tema alternatif dan bandingkan dengan kriteria yang disepakati (anggaran, minat peserta tahun ini, kebaruan, kemudahan); minta usulan & keberatan secara anonim; putuskan berdasarkan hasil perbandingan, bukan kelekatan pada yang lama."},
{n:81,type:"mcq",micro:"Keputusan dengan banyak pemangku kepentingan",q:"OSIS memutuskan alokasi dana terbatas ke beberapa kegiatan yang semuanya penting bagi kelompok berbeda. Pendekatan yang paling adil & efektif:",options:["Sepakati kriteria bersama (jumlah siswa terdampak, urgensi, dampak jangka panjang, kesetaraan antar kelompok), nilai tiap usulan secara terbuka, jelaskan keputusan","Berikan seluruh dana kepada kegiatan yang diusulkan oleh kelompok yang paling vokal dan paling banyak bicara, tanpa menilai usulan lain secara terbuka maupun menjelaskan alasannya","Bagi rata dana ke semua kegiatan dalam jumlah yang sama persis tanpa memandang jumlah siswa terdampak, urgensi, atau kebutuhan nyata dari tiap kegiatan yang diusulkan"],answer:0,explain:"Keputusan alokasi sumber daya di antara kepentingan yang bersaing paling baik lewat kriteria yang disepakati dan proses terbuka.",hint:"Bagaimana membuat kelompok yang tidak mendapat dana tetap merasa prosesnya adil?"},
{n:82,type:"mcq",micro:"Keputusan yang mengikat masa depan",q:"Keputusan 'menandatangani kesepakatan 1 tahun dengan sponsor yang membatasi kegiatan tertentu' perlu ekstra hati-hati karena...",options:["Kontrak selalu menguntungkan karena ada dana dari sponsor, sehingga isi pembatasannya tidak perlu dibaca teliti","Sulit dibatalkan dan mengikat pilihan selama setahun; hasil terburuk (menyesal & terikat) harus benar-benar bisa ditanggung","Semua keputusan sama saja tingkat bahayanya, sehingga keputusan ini tidak butuh pertimbangan khusus apa pun"],answer:1,explain:"Untuk keputusan yang sulit dibalik dan berdampak panjang, standar bukti dan pertimbangannya harus lebih tinggi.",hint:"Apa yang terjadi kalau setelah 3 bulan kalian menyesal tapi terikat 9 bulan lagi?"},
{n:83,type:"tf",micro:"Keputusan besar sebaiknya 'diuji' dulu bila mungkin",q:"Benar atau Salah: Bila memungkinkan, mengubah keputusan besar yang sulit dibalik menjadi serangkaian langkah kecil yang bisa diuji (uji coba, periode percobaan, komitmen bertahap) mengurangi risiko.",answer:true,explain:"Mengurai keputusan besar menjadi taruhan kecil yang informatif memungkinkan belajar sebelum berkomitmen penuh.",hint:"Bisakah kamu 'menyewa sebelum membeli' dalam keputusan ini?"},
{n:84,type:"mcq",micro:"Keputusan di bawah informasi yang bertentangan",q:"Dua sumber tepercaya memberi saran berlawanan. Langkah yang masuk akal:",options:["Ikuti yang lebih tua","Lempar koin","Cari tahu MENGAPA mereka berbeda — asumsi/pengalaman/kepentingan apa yang berbeda — lalu nilai mana yang lebih cocok dengan situasimu"],answer:2,explain:"Ketidaksepakatan ahli sering berasal dari asumsi atau konteks berbeda. Memahami sumbernya membantu memutuskan mana yang relevan untukmu.",hint:"Apa yang membuat kedua orang itu sampai pada kesimpulan berbeda?"},
{n:85,type:"order",micro:"Proses keputusan besar yang lengkap",q:"Urutkan langkah mengambil keputusan hidup yang besar (misalnya memilih jurusan/sekolah lanjutan).",items:["Perjelas apa yang benar-benar kamu putuskan, dan apa yang paling penting bagimu (kriteria & bobot)","Kumpulkan informasi nyata: kunjungi, tanya orang yang menjalani, cek fakta biaya/jarak/prospek","Daftar pilihan, timbang terhadap kriteria & skenario ketidakpastian, periksa bias","Pilih, tuliskan alasan & asumsi, tetapkan titik tinjau, lalu berkomitmen menjalankannya"],answer:[0,1,2,3],explain:"Perjelas & kriteria → kumpulkan info nyata → timbang & periksa bias → pilih, catat alasan, tetapkan titik tinjau, komit.",hint:"Kamu perlu tahu apa yang penting bagimu sebelum informasi apa pun berguna."},
{n:86,type:"mcq",micro:"Keputusan dan siapa yang menanggung akibat",q:"Saat orang lain mendorongmu keras ke sebuah pilihan, pertanyaan yang menjernihkan:",options:["'Siapa yang akan hidup dengan akibat keputusan ini setiap hari?' — kalau itu kamu, suaramu harus paling berbobot","'Siapa yang paling keras berbicara dan paling sering mendesak kamu, sehingga pendapatnya harus paling kamu turuti?'","'Siapa yang paling tua dan paling lama hidup di antara mereka, sehingga ia pasti yang paling tahu keputusan benar?'"],answer:0,explain:"Masukan orang lain berharga, tapi bobot terbesar dalam keputusan pribadi ada pada orang yang menanggung konsekuensinya.",hint:"Orang yang mendorongmu — apakah mereka yang akan menjalani hasilnya?"},
{n:87,type:"mcq",micro:"Keputusan yang tampak mendesak padahal penting-tidak-mendesak",q:"Membedakan keputusan yang benar-benar mendesak dari yang hanya terasa mendesak berguna karena...",options:["Yang mendesak selalu yang paling penting untuk dikerjakan lebih dulu, sehingga yang penting tapi tidak mendesak boleh diabaikan atau ditunda tanpa batas waktu selamanya","Yang penting tapi tidak mendesak (kesehatan, hubungan, tujuan jangka panjang) sering terabaikan demi yang mendesak tapi kurang penting — kenali dan lindungi waktu untuk yang penting","Semua keputusan sama mendesaknya bagi semua orang, jadi tidak ada gunanya membedakan mana yang penting dan mana yang tidak, serta tidak perlu melindungi waktu untuk apa pun"],answer:1,explain:"Keputusan besar dalam hidup sering yang penting-tapi-tidak-mendesak. Menyadari ini membantu memberinya perhatian yang layak.",hint:"Keputusan apa yang terus kamu tunda karena selalu ada hal 'lebih mendesak'?"},
{n:88,type:"tf",micro:"Keputusan bisa ditinjau tanpa berarti plin-plan",q:"Benar atau Salah: Sekali kamu berkomitmen pada sebuah keputusan, mengubahnya selalu berarti kamu tidak berpendirian — bahkan bila muncul informasi baru yang signifikan.",answer:false,explain:"Berpendirian bukan berarti tidak pernah berubah; itu berarti tidak berubah karena angin sepoi. Meninjau ulang karena fakta besar yang baru atau perubahan keadaan besar adalah tanda pemikir yang matang.",hint:"Apakah nakhoda yang mengubah haluan karena badai itu 'plin-plan'?"},
{n:89,type:"mcq",micro:"Keputusan dan ketidaktahuan yang jujur",q:"Untuk keputusan besar, mengakui 'ada hal-hal penting yang tidak bisa aku ketahui sekarang' mendorong kamu untuk...",options:["Menunda keputusan selamanya","Memilih acak","Memilih pilihan yang tetap cukup baik di berbagai kemungkinan, menjaga fleksibilitas, dan menetapkan titik tinjau — bukan berpura-pura yakin"],answer:2,explain:"Kerendahan hati tentang ketidakpastian menghasilkan keputusan yang lebih tahan banting: tidak bertaruh semuanya pada satu ramalan.",hint:"Kalau kamu tidak bisa tahu masa depan, pilihan seperti apa yang paling aman?"},
{n:90,type:"mcq",micro:"Menutup keputusan dengan baik",q:"Setelah keputusan besar diambil, langkah penutup yang sehat:",options:["Berkomitmen sungguh-sungguh menjalankannya (bukan setengah hati sambil menyesali), sambil tetap membuka mata pada informasi yang benar-benar mengubah gambaran","Terus membandingkan keputusanmu dengan pilihan yang tidak diambil setiap hari, sambil menyesalinya, supaya kamu bisa menilai apakah keputusanmu benar atau tidak benar","Melupakan sepenuhnya bahwa kamu pernah memutuskan sesuatu, termasuk informasi baru yang bisa mengubah gambaran keputusan itu, dan menjalankannya tanpa perhatian apa pun lagi"],answer:0,explain:"Setelah menimbang cukup, energi terbaik dipakai untuk membuat pilihan itu berhasil — bukan untuk terus meratapi jalan yang tidak diambil.",hint:"Apa yang lebih membantu: menjalankan pilihan dengan sungguh-sungguh, atau terus menoleh ke belakang?"},
{n:91,type:"mcq",micro:"Keputusan sebagai keterampilan yang dilatih",q:"Cara menjadi lebih baik dalam mengambil keputusan dari waktu ke waktu:",options:["Menghindari membuat keputusan sebanyak mungkin, supaya kamu tidak pernah perlu menanggung akibat dari kesalahan","Catat keputusan penting & alasannya, tinjau hasilnya nanti, pisahkan 'keputusan buruk' dari 'nasib buruk', dan sesuaikan proses","Berharap pengalaman datang sendiri seiring bertambahnya usia, tanpa perlu mencatat atau meninjau keputusan apa pun"],answer:1,explain:"Umpan balik yang disengaja pada proses keputusan — bukan hanya hasil — adalah cara utama keterampilan ini tumbuh.",hint:"Bagaimana kamu tahu apakah proses keputusanmu perlu diperbaiki?"},
{n:92,type:"tf",micro:"Keputusan menghubungkan semua keterampilan pemecahan masalah",q:"Benar atau Salah: Mengambil keputusan adalah keterampilan yang berdiri sendiri dan tidak berhubungan dengan memahami situasi, berpikir kreatif, menilai kritis, atau mengevaluasi hasil.",answer:false,explain:"Pengambilan keputusan justru tempat semua keterampilan pemecahan masalah bertemu: dari mengenali apa yang diputuskan, memecah pilihan, menemukan opsi baru, menimbang, sampai belajar dari hasilnya.",hint:"Apakah memutuskan bisa dilepaskan dari memahami, menimbang, dan mengevaluasi?"},
{n:93,type:"mcq",micro:"Keputusan yang menghormati orang lain",q:"Saat keputusanmu memengaruhi orang lain secara signifikan, praktik yang baik:",options:["Putuskan diam-diam dan biarkan mereka mengetahuinya sendiri nanti, supaya tidak ada yang sempat berdebat denganmu","Selalu ikuti apa pun yang mereka inginkan, walaupun itu berlawanan dengan kriteria dan keadaanmu sendiri","Beri tahu mereka, dengarkan pandangan mereka sebelum memutuskan bila memungkinkan, dan jelaskan alasannya setelahnya"],answer:2,explain:"Transparansi dan mendengarkan tidak berarti menyerahkan keputusan — tapi menghormati orang yang terdampak.",hint:"Bagaimana kamu ingin diperlakukan kalau keputusan orang lain sangat memengaruhi hidupmu?"},
{n:94,type:"open",micro:"Keputusan kompleks nyata dari awal sampai komitmen",q:"Pilih keputusan nyata yang sedang atau akan kamu hadapi (agak besar, tidak trivial). Kerjakan seluruh proses: (1) perjelas keputusan & kriteria berbobot, (2) daftar pilihan termasuk 'tidak berubah' & pilihan kreatif ke-3, (3) untuk tiap pilihan: akibat baik/buruk + ketidakpastian utama, (4) matriks skor + syarat wajib, (5) periksa 2 bias yang mungkin memengaruhimu, (6) keputusan + alasan + rencana bila hasil buruk + titik tinjau.",explain:"Kapstone menuntut proses lengkap: kriteria berbobot, opsi termasuk status quo & opsi kreatif, akibat & ketidakpastian, matriks, pemeriksaan bias spesifik, dan keputusan dengan mitigasi + titik tinjau — idealnya memilih langkah reversibel dulu bila memungkinkan.",hint:"Sertakan opsi ke-3 yang menggabungkan atau melampaui 'ya/tidak', dan pilih langkah yang bisa diuji dulu bila keputusannya besar.",sample:"Jawaban lengkap mengisi keenam bagian dengan kedalaman nyata. Contoh domain: 'apakah pindah dari kelas pagi ke kelas siang (jika sekolah membolehkan) agar bisa membantu usaha keluarga di pagi hari'. (1) Kriteria: dampak ke nilai (×3), membantu keluarga (×3), kesehatan/tidur (×2), pertemanan (×1). (2) Pilihan: A pindah ke siang; B tetap pagi; C tetap pagi tapi bantu keluarga hanya akhir pekan + sore (opsi ke-3 gabungan); D tetap pagi, keluarga cari bantuan lain. (3) A: + bisa bantu tiap pagi, mungkin lebih segar; − teman lama di pagi, guru berbeda, adaptasi; ketidakpastian: apakah kelas siang kualitas pengajarannya sama. C: + tidak mengubah sekolah; − bantuan ke keluarga terbatas; ketidakpastian: apakah cukup meringankan. (4) skor... (5) Bias: status quo (takut pindah karena nyaman) dan 'FOMO pertemanan' (terlalu memberatkan faktor teman dibanding nilai & keluarga) — minta pendapat orang tua & wali kelas untuk mengimbangi. (6) Keputusan: coba C selama 1 bulan dulu (reversibel); kalau keluarga masih sangat terbebani DAN nilaiku stabil, ajukan pindah ke siang di semester berikutnya. Titik tinjau: akhir bulan, lihat beban keluarga & nilai ulangan."},
{n:95,type:"mcq",micro:"Keputusan dan waktu terbaik untuk mengambilnya",q:"Untuk keputusan penting yang tidak mendesak, waktu terbaik mengambilnya sering...",options:["Setelah mengumpulkan informasi kunci dan dalam kondisi tenang & istirahat cukup — tidak di puncak emosi atau kelelahan, tapi juga tidak ditunda tanpa batas","Sesegera mungkin pada saat itu juga, apa pun kondisimu sedang marah, lelah, atau lapar, karena menunda hanya akan membuat keputusannya makin sulit dan membingungkan","Ditunda sampai benar-benar terpaksa dan tidak ada lagi waktu tersisa, karena pada saat terakhir itulah keadaan paling jelas dan tidak ada pilihan lain lagi yang tersisa"],answer:0,explain:"Kualitas keputusan dipengaruhi oleh informasi DAN kondisi pengambilnya. Pilih momen ketika kamu punya keduanya.",hint:"Kapan pemikiranmu paling jernih?"},
{n:96,type:"mcq",micro:"Keputusan tim: peran yang jelas",q:"Agar keputusan tim tidak macet, berguna menetapkan di awal...",options:["Bahwa tidak ada aturan sama sekali tentang cara memutuskan atau siapa yang berwenang, supaya tim bebas menyesuaikan dengan suasana dan keinginan anggota pada saat itu","Bagaimana keputusan akhirnya diambil (konsensus? voting? satu orang memutuskan setelah mendengar semua?) dan siapa yang berwenang bila buntu","Bahwa semua anggota harus setuju seratus persen tanpa kecuali sebelum keputusan apa pun boleh diambil, walaupun itu membuat tim berdebat tanpa akhir dan tidak pernah selesai"],answer:1,explain:"Menyepakati 'aturan pengambilan keputusan' sebelum berdiskusi mencegah kebuntuan dan pertengkaran tentang proses.",hint:"Apa yang terjadi kalau tim berdebat tanpa pernah sepakat bagaimana cara memutuskannya?"},
{n:97,type:"tf",micro:"Tidak semua keputusan layak analisis mendalam",q:"Benar atau Salah: Menghabiskan waktu dan energi yang sama untuk memilih rasa es krim dan untuk memilih sekolah lanjutan adalah pemakaian sumber daya berpikir yang tidak seimbang.",answer:true,explain:"Sesuaikan usaha dengan taruhan. Analisis mendalam untuk keputusan sepele, dan keputusan cepat untuk hal besar, sama-sama keliru.",hint:"Apakah semua keputusan pantas mendapat porsi perhatian yang sama?"},
{n:98,type:"mcq",micro:"Menutup: keputusan yang baik",q:"Keputusan yang baik terutama dinilai dari...",options:["Apakah hasilnya bagus pada akhirnya, titik — karena hasil yang baik berarti prosesnya pasti benar, sehingga tidak perlu memeriksa kriteria, pilihan, ketidakpastian, bias, ataupun menetapkan komitmen dan titik tinjau sama sekali","Apakah keputusan itu dibuat dengan sangat cepat dan tegas tanpa ragu sedikit pun, karena keputusan yang cepat selalu lebih baik daripada yang lambat, tanpa perlu melihat bagaimana prosesnya, informasinya, atau pilihan yang dipertimbangkan","Prosesnya: apakah keputusan apa & kriteria diperjelas, pilihan (termasuk kreatif) dipertimbangkan, informasi & ketidakpastian ditimbang, bias diperiksa, dan ada komitmen + titik tinjau — bukan hanya dari apakah hasilnya kebetulan bagus"],answer:2,explain:"Hasil dipengaruhi keberuntungan; proses yang baik meningkatkan peluang hasil baik secara konsisten dan bisa dipelajari.",hint:"Apa yang bisa kamu kendalikan: proses atau keberuntungan?"},
{n:99,type:"mcq",micro:"Ringkasan: pengambilan keputusan",q:"Rangkuman paling tepat:",options:["Perjelas keputusan & kriteria (berbobot); daftar pilihan termasuk 'tidak berubah' & opsi kreatif; timbang akibat, ketidakpastian, & risiko; periksa bias & (untuk tim) proses yang adil; sesuaikan usaha dengan taruhan & reversibilitas; pilih, catat alasan, tetapkan titik tinjau, lalu berkomitmen — dan nilai keputusan dari prosesnya, bukan hanya hasil","Ikuti saja perasaan pertama yang muncul di hati lalu jalankan segera, tanpa memperjelas kriteria berbobot, mendaftar pilihan termasuk opsi kreatif dan 'tidak berubah', menimbang akibat dan risiko, memeriksa bias, ataupun mencatat alasan serta menetapkan kapan keputusan itu ditinjau kembali — dan nilai keputusan hanya dari hasilnya","Serahkan semua keputusan kepada orang lain yang kamu percayai, sehingga kamu tidak perlu menimbang kriteria, risiko, ataupun reversibilitas, tidak perlu memeriksa apakah prosesnya adil bagi tim, tidak perlu mencatat alasan, dan tidak ikut bertanggung jawab atas akibat keputusan yang diambil olehnya"],answer:0,explain:"Pengambilan keputusan yang baik menggabungkan kejelasan tujuan, pilihan yang cukup luas, penimbangan risiko, kesadaran bias, proses yang adil, kalibrasi usaha, komitmen, dan evaluasi proses.",hint:"Gabungkan: perjelas → pilihan luas → timbang risiko → cek bias → kalibrasi usaha → komit & tinjau."},
{n:100,type:"open",micro:"Kapstone: catatan keputusan yang bisa dipertahankan",q:"Ambil keputusan nyata (pribadi atau kelompok) yang harus kamu ambil dalam waktu dekat. Buat 'catatan keputusan' lengkap yang bisa kamu tunjukkan & pertahankan ke orang lain: (1) keputusan & mengapa perlu diambil sekarang, (2) kriteria + bobot + syarat wajib, (3) semua pilihan dipertimbangkan (min. 4, termasuk status quo & satu opsi kreatif) + alasan yang gugur, (4) matriks skor / analisis akibat & ketidakpastian, (5) bias yang kamu waspadai & bagaimana kamu mengimbanginya, (6) keputusan akhir + biaya peluang yang diterima + rencana bila hasil buruk + kapan/berdasarkan apa akan ditinjau ulang.",explain:"Kapstone menghasilkan artefak nyata yang menunjukkan seluruh proses pengambilan keputusan yang matang dan bisa dipertanggungjawabkan — menutup domain Pemecahan Masalah dengan keterampilan memilih di antara jalan-jalan yang terbuka.",hint:"Tulis untuk pembaca yang skeptis: setiap klaim ('opsi B gugur', 'aku tidak bias di sini') harus didukung alasan yang terlihat.",sample:"Catatan keputusan yang baik terisi lengkap keenam bagian dengan: alasan urgensi yang jujur (bukan tekanan buatan); kriteria yang benar-benar mencerminkan nilaimu, berbobot, dengan syarat wajib bila ada; minimal 4 pilihan nyata termasuk 'tidak berubah' dan satu opsi yang menggabungkan/melampaui pilihan biner, dengan alasan gugur yang menyebut kriteria; analisis yang menimbang akibat baik & buruk plus ketidakpastian utama tiap pilihan (matriks skor atau analisis skenario); identifikasi 2–3 bias spesifik yang mungkin memengaruhimu (mis. status quo, biaya hangus, groupthink, penjangkaran, FOMO) dengan langkah nyata mengimbanginya (minta pandangan penantang, bentuk penilaian sebelum lihat harga, dll.); dan keputusan akhir yang menyebut apa yang dikorbankan (biaya peluang), rencana konkret bila hasil buruk, dan titik tinjau yang jelas ('tinjau setelah 1 bulan, atau lebih cepat bila X terjadi'). Panjang wajar: 250–400 kata, ditulis seolah harus dipertahankan di hadapan guru/orang tua."},
];
